import os
import sqlite3
from fastapi import FastAPI, Header, HTTPException, Depends
from fastapi.responses import HTMLResponse

app = FastAPI()
DB_FILE = os.getenv("DB_FILE", "/data/notes.db")
API_KEY = os.environ["API_KEY"]

def require_key(x_api_key: str = Header()):
    if x_api_key != API_KEY:
        raise HTTPException(status_code=401, detail="Unauthorized")

@app.get("/health")
def health():
    return {"status": "ok"}

@app.get("/notes", response_class=HTMLResponse, dependencies=[Depends(require_key)])
def notes(q: str = ""):
    with sqlite3.connect(DB_FILE) as db:
        rows = db.execute("SELECT body FROM notes WHERE body LIKE ?", ("%" + q + "%",)).fetchall()
    return "<ul>" + "".join("<li>" + row[0] + "</li>" for row in rows) + "</ul>"
